create table folders (id integer generated always as identity primary key, organization_id integer not null, title text not null, updated_at timestamptz not null default now());

create table lines (id integer generated always as identity primary key, folder_id integer not null references folders (id), organization_id integer not null,
  position integer not null , body text not null, updated_at timestamptz not null default now(), unique (folder_id, position)); 
create table tight_lines (id integer generated always as identity primary key, folder_id integer not null references folders (id), organization_id integer not null,
  position integer not null check (position <= 3), body text not null, updated_at timestamptz not null default now(), unique (folder_id, position)); 
create table guarded (id integer generated always as identity primary key, folder_id integer not null references folders (id), organization_id integer not null,
  position integer not null , body text not null, updated_at timestamptz not null default now(), unique (folder_id, position));

